      "path": "src/App.tsx",
      "language": "typescript",
      "content": "import { useState } from "react";
import { BudgetForm } from "./components/BudgetForm";
import { MealPlan } from "./components/MealPlan";
import { ShoppingList } from "./components/ShoppingList";
import { generatePlan } from "./planner";
import type { PlanResult } from "./types";

export default function App() {
  const [result, setResult] = useState<PlanResult | null>(null);

  function handleSubmit(budget: number, familySize: number) {
    // PDD § Objective: plan a week of dinners on a given budget
    // PDD § I/O contract: Input budget + family size → days[] + shoppingList[]
    setResult(generatePlan(budget, familySize));
  }

  return (
    <main style={{ fontFamily: "sans-serif", maxWidth: 720, margin: "0 auto", padding: "1rem" }}>
      <h1>Weekly Dinner Planner</h1>
      <BudgetForm onSubmit={handleSubmit} />
      {result && (
        <>
          <MealPlan days={result.days} />
          <ShoppingList items={result.shoppingList} totalCost={result.totalCost} budget={result.budget} />
        </>
      )}
    </main>
  );
}
