    {
      "path": "src/types.ts",
      "language": "typescript",
      "content": "// PDD § I/O contract
export interface Day {
  day: string;
  meal: string;
  costPerServing: number;
}

export interface ShoppingItem {
  ingredient: string;
  estimatedCost: number;
}

export interface PlanResult {
  budget: number;
  totalCost: number;
  days: Day[];
  shoppingList: ShoppingItem[];
}
"
    },
    {
      "path": "src/planner.ts",
      "language": "typescript",
      "content": "import type { PlanResult, Day, ShoppingItem } from "./types";

// PDD § Objective: 7 distinct meals, total cost ≤ budget
// PDD § Success criteria: Total cost ≤ budget; 7 distinct meals.

const MEAL_TEMPLATES: Array<{ meal: string; costPerServing: number; ingredients: string[] }> = [
  { meal: "Spaghetti Bolognese", costPerServing: 2.5, ingredients: ["pasta", "ground beef", "tomato sauce"] },
  { meal: "Chicken Stir-fry", costPerServing: 3.0, ingredients: ["chicken breast", "mixed vegetables", "soy sauce", "rice"] },
  { meal: "Lentil Soup", costPerServing: 1.5, ingredients: ["lentils", "carrots", "celery", "onion", "broth"] },
  { meal: "Tacos", costPerServing: 2.8, ingredients: ["ground beef", "taco shells", "lettuce", "cheese", "salsa"] },
  { meal: "Veggie Curry", costPerServing: 2.0, ingredients: ["chickpeas", "spinach", "coconut milk", "curry paste", "rice"] },
  { meal: "Baked Salmon", costPerServing: 4.0, ingredients: ["salmon fillets", "lemon", "dill", "potatoes"] },
  { meal: "Margherita Pizza", costPerServing: 1.8, ingredients: ["pizza dough", "mozzarella", "tomato sauce", "basil"] },
];

const DAYS_OF_WEEK = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

export function generatePlan(budget: number, familySize: number): PlanResult {
  // TODO(code-dj): § I/O contract — implement smarter meal selection/swapping
  // to optimise cost within budget rather than using fixed templates.

  const days: Day[] = [];
  const ingredientMap = new Map<string, number>();
  let totalCost = 0;

  for (let i = 0; i < 7; i++) {
    const template = MEAL_TEMPLATES[i];
    const mealCost = template.costPerServing * familySize;
    totalCost += mealCost;

    days.push({
      day: DAYS_OF_WEEK[i],
      meal: template.meal,
      costPerServing: template.costPerServing,
    });

    for (const ingredient of template.ingredients) {
      ingredientMap.set(
        ingredient,
        (ingredientMap.get(ingredient) ?? 0) + template.costPerServing * familySize
      );
    }
  }

  // PDD § Success criteria: warn if over budget but still return plan
  const shoppingList: ShoppingItem[] = Array.from(ingredientMap.entries()).map(
    ([ingredient, estimatedCost]) => ({ ingredient, estimatedCost })
  );

  return { budget, totalCost, days, shoppingList };
}
"
