    {
      "path": "src/components/BudgetForm.tsx",
      "language": "typescript",
      "content": "import { useState } from "react";

// PDD § I/O contract: inputs are budget and family size
interface Props {
  onSubmit: (budget: number, familySize: number) => void;
}

export function BudgetForm({ onSubmit }: Props) {
  const [budget, setBudget] = useState<number>(120);
  const [familySize, setFamilySize] = useState<number>(4);

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    onSubmit(budget, familySize);
  }

  return (
    <form onSubmit={handleSubmit} style={{ marginBottom: "1.5rem" }}>
      <label style={{ display: "block", marginBottom: "0.5rem" }}>
        Budget ($):
        <input
          type="number"
          min={1}
          value={budget}
          onChange={(e) => setBudget(Number(e.target.value))}
          style={{ marginLeft: "0.5rem" }}
        />
      </label>
      <label style={{ display: "block", marginBottom: "0.5rem" }}>
        Family size:
        <input
          type="number"
          min={1}
          value={familySize}
          onChange={(e) => setFamilySize(Number(e.target.value))}
          style={{ marginLeft: "0.5rem" }}
        />
      </label>
      <button type="submit">Generate Plan</button>
    </form>
  );
}
"
    },
    {
      "path": "src/components/MealPlan.tsx",
      "language": "typescript",
      "content": "import type { Day } from "../types";

// PDD § I/O contract: output days[]
interface Props {
  days: Day[];
}

export function MealPlan({ days }: Props) {
  return (
    <section style={{ marginBottom: "1.5rem" }}>
      <h2>7-Day Meal Plan</h2>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th style={{ textAlign: "left", borderBottom: "1px solid #ccc", padding: "0.4rem" }}>Day</th>
            <th style={{ textAlign: "left", borderBottom: "1px solid #ccc", padding: "0.4rem" }}>Meal</th>
            <th style={{ textAlign: "right", borderBottom: "1px solid #ccc", padding: "0.4rem" }}>Cost/serving</th>
          </tr>
        </thead>
        <tbody>
          {days.map((d) => (
            <tr key={d.day}>
              <td style={{ padding: "0.4rem" }}>{d.day}</td>
              <td style={{ padding: "0.4rem" }}>{d.meal}</td>
              <td style={{ textAlign: "right", padding: "0.4rem" }}>${d.costPerServing.toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
"
    },
    {
      "path": "src/components/ShoppingList.tsx",
      "language": "typescript",
      "content": "import type { ShoppingItem } from "../types";

// PDD § I/O contract: output shoppingList[]
// PDD § Success criteria: surface whether total cost ≤ budget
interface Props {
  items: ShoppingItem[];
  totalCost: number;
  budget: number;
}

export function ShoppingList({ items, totalCost, budget }: Props) {
  const withinBudget = totalCost <= budget;

  return (
    <section>
      <h2>Shopping List</h2>
      <p style={{ color: withinBudget ? "green" : "red", fontWeight: "bold" }}>
        Total estimated cost: ${totalCost.toFixed(2)} / ${budget.toFixed(2)} budget —{" "}
        {withinBudget ? "✅ Within budget" : "⚠️ Over budget"}
      </p>
      <ul>
        {items.map((item) => (
          <li key={item.ingredient}>
            {item.ingredient} — ${item.estimatedCost.toFixed(2)}
          </li>
        ))}
      </ul>
      {/* TODO(code-dj): § I/O contract — group ingredients, add quantity/unit fields */}
    </section>
  );
}
"
    }
